insert into legs (season_id, n, beta, tags, team_rating, surface_text) values
((select id from seasons where year=2026), 1, 'Trail has switchbacks with loose gravel and tree roots — be careful, saw several people fall. Steep climb going into Eureka, potential to walk some of it. Easy downhill through town, followed by a tough gravel climb to the finish. Could see this leg rated very hard.', '["Loose gravel + roots", "Steep climb"]'::jsonb, 'Very Hard', 'Trail / pavement / gravel'),
((select id from seasons where year=2026), 2, 'A lot of climbs on this one. Moderate, but arguably hard. Pay attention to turn signs and dogs.', '["Dogs", "Watch the turns"]'::jsonb, 'Hard', 'All pavement'),
((select id from seasons where year=2026), 3, 'Hard for sure. Super rocky path — even the vans can''t follow it. You run across a dry river bed and finish up a steep, narrow hiking trail to the highway. Many had to walk a little.', '["No van access", "Rocky"]'::jsonb, null, '75% gravel/trail · 25% pavement'),
((select id from seasons where year=2026), 4, 'Starts on paved highway with moderate traffic. Mostly flat. Finishes with a descent on a rocky dirt road. Closer to easy.', '["Traffic"]'::jsonb, 'Easy', 'Pavement / gravel'),
((select id from seasons where year=2026), 5, 'Very steep climbs with some hard descents — and beautiful views. You''ll have hills where you have to walk, followed by steep descents where you can run fast, but not too fast or you might fall. Pay attention to footing. Very challenging leg.', '["Footing", "Walk the steeps", "Views"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 6, 'Easy paved highway. Rated moderate, but I would rate it easy. Nice rolling flats on pavement.', '[]'::jsonb, 'Easy', '¼ mile dirt, then all pavement'),
((select id from seasons where year=2026), 7, 'Rolling hills with two big inclines. Easy to go fast on the downhill. A lot of good shade.', '["Shaded"]'::jsonb, null, '100% trail'),
((select id from seasons where year=2026), 8, 'Anticipate loose rocks, exposed roots and heavy leaf coverage. Several descents and moderate climbs. Finishes with a transition to paved road leading directly to War Eagle. GPS navigation recommended for the trail (sorry Benny).', '["GPS recommended", "Rocks + roots + leaves"]'::jsonb, null, 'Mostly trail · last mile pavement'),
((select id from seasons where year=2026), 9, 'Lightly hilly countryside with a few medium-sized hills along the way. Seems moderate.', '[]'::jsonb, 'Moderate', '60% pavement · 40% gravel'),
((select id from seasons where year=2026), 10, 'You go up a gnarly hill when you reach gravel — the rock was chunky and challenging for road shoes. Back onto the highway, then gravel again. Both my favorite and least favorite leg. Rated hard, and I definitely agree.', '["Chunky rock", "Shoe choice matters"]'::jsonb, null, '½ mi pavement · 7 mi gravel · 1 mi pavement'),
((select id from seasons where year=2026), 11, 'Easy downhill to start. Rolling hills with a couple decent climbs. Gravel was in good shape. Turns onto Hwy 23, which is flat — but be on the lookout for traffic.', '["Traffic on Hwy 23"]'::jsonb, null, '⅓ gravel · ⅔ pavement'),
((select id from seasons where year=2026), 12, 'Big decline at the pavement portion. The last half mile is trail and the toughest part — the stairs on the trail are slippery.', '["Slippery stairs"]'::jsonb, null, 'Mostly gravel / pavement · last ½ mi gravel'),
((select id from seasons where year=2026), 13, 'Cross the street to the dirt road — if you go over the second bridge, you went too far. Pavement leads to a ferry pickup to cross Hwy 412, then finish with a half-mile run after.', '["Navigation", "Hwy 412 ferry crossing"]'::jsonb, null, '⅓ pavement · ⅔ gravel'),
((select id from seasons where year=2026), 14, 'Several turns, and some of the signs were removed or hard to see. Pay attention — have the van stick with the runner on this one.', '["Navigation!", "Van should shadow runner"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 15, 'Pitch black. Some little rollers with one mild climb. I would rate it moderate.', '["Pitch black \u2014 lights!"]'::jsonb, 'Moderate', '2 mi gravel · 5 mi pavement'),
((select id from seasons where year=2026), 16, 'Spooky as hell, but if you can get past that, a quiet and peaceful run. Rated moderate, but I would rate it easy.', '["Dark + spooky"]'::jsonb, 'Easy', '40% pavement · 60% gravel'),
((select id from seasons where year=2026), 17, 'Appropriately moderate. The hills were nasty getting up, but you end on pavement with a consistent decline — you make up a ton of time on the downhill. Push hard on the uphill, because you can catch your breath at the end.', '["Nasty ups, fast finish"]'::jsonb, null, '75% gravel · 25% pavement'),
((select id from seasons where year=2026), 18, 'You can definitely run faster on this leg. Pay attention to turns and traffic on the final mile. Overall a flat and nice leg — more towards easy.', '["Turns + traffic, final mile"]'::jsonb, 'Easy', 'Pavement / gravel / pavement · about half and half'),
((select id from seasons where year=2026), 19, 'Leaves the city and heads out onto a paved road. Very dark. Mostly flat with some light-to-medium rolling hills. More moderate.', '["Very dark"]'::jsonb, 'Moderate', '100% pavement'),
((select id from seasons where year=2026), 20, 'Easy breezy! A few hills.', '[]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 21, 'Very easy run — smooth road and flat. The only lookout worth noting is an uneven bridge, which can pose a challenge running at night.', '["Uneven bridge at night"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 22, 'One steady climb the whole way — very gradual, but steep at times. It just keeps going! Hard to hold the heart rate down. Be ready to climb and go slow on this one. Leans towards hard.', '["Sustained climb"]'::jsonb, 'Hard', 'Gravel / pavement · close to half and half'),
((select id from seasons where year=2026), 23, 'Starts off flat and smooth, but gets very rough and rugged about 3 miles in and stays that way until the end.', '["Rugged after mile 3"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 24, 'Even though it''s pavement, it was in very bad shape at times — pay attention. A lot of hills and very desolate. You will walk some. It felt good to get to Lake Fort Smith and be done with this one.', '["Broken pavement", "Desolate"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 25, 'All uphill for 1.7 miles before a constant downhill to Chester. The downhill felt like it went on forever. Rated hard, and I definitely agree.', '["1.7 mi opening climb", "Endless downhill"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 26, 'Take a left onto the main road out of the parking lot, immediately beginning a substantial climb. Once you reach the summit, bear left to transition to a dirt road for your exchange.', '["Climbs right off the start"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 27, 'Arguably a hard rating. The hills were a beast and the terrain was difficult. There''s a huge hill between miles 5 and 6 — you will likely walk some. Save yourself on the initial hills, because the last one is painful.', '["Beast hills", "Big hill mi 5\u20136"]'::jsonb, 'Hard', '100% gravel'),
((select id from seasons where year=2026), 28, 'Smooth sailing! Nice paved road, beautiful views. Some substantial uphill, but still moderate overall.', '["Views"]'::jsonb, null, 'Half pavement · half gravel'),
((select id from seasons where year=2026), 29, 'Lots of rolling hills with three big climbs — every downhill was met with a climb. Windy road with very little shoulder. Would recommend a flagger.', '["Flagger recommended", "No shoulder"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 30, 'A lot of gradual climbs for the first 4–5 miles. Take your time — you''ll need it for the brutal descent into Devil''s Den: switchbacks and high traffic, with over 800 ft of descent in the last couple of miles. Highly recommend a flagger.', '["Flagger recommended", "Brutal descent", "Switchbacks + traffic"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 31, 'Short trail coming out of the park with uneven terrain. Once you reach Hwy 16 it''s flat until 2.3 miles in — then you climb!! Climb the rest of the way. Walked a few stretches to keep the heart rate down.', '["Climb from mile 2.3 on"]'::jsonb, null, '½ mi trail · 3.5 mi pavement · rest gravel'),
((select id from seasons where year=2026), 32, 'Transition is about halfway, where you''ll make a left. Rolling hills throughout, followed by a short climb to the finish.', '[]'::jsonb, null, '50% pavement · 50% gravel'),
((select id from seasons where year=2026), 33, 'A lot of curves in the road towards the end and no shoulder to retreat to — be careful! Recommend a flagger.', '["Flagger recommended", "Blind curves"]'::jsonb, null, 'Pavement / gravel'),
((select id from seasons where year=2026), 34, 'Nice easy leg with a lot of descents. If you have anything left, you can make good time on this one.', '["Fast descents"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 35, 'Start on dirt with a steady incline, finish on pavement with a decline. Next to a busy road — stay alert!', '["Busy road"]'::jsonb, null, '½ gravel · ½ pavement'),
((select id from seasons where year=2026), 36, 'Light rolling hills. Ferry at the Hwy 62 intersection — park your car on the same side as the runner and ferry across the street. Ends at the finish line at Prairie Grove Battlefield Park!', '["Hwy 62 ferry crossing", "FINISH!"]'::jsonb, null, 'Pavement · 1 mi gravel · pavement')
